const state = { section:'home', quizIndex:0, score:0, answered:false, currentCourse:null, currentLesson:null, orientationQuizIndex:0, orientationQuizScore:0, orientationAnswered:false };

function esc(value){ return String(value ?? '').replace(/[&<>\"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[ch])); }
function allCourses(){ return PATHWAYS.flatMap(p => p.courses.map(c => ({...c, pathwayTitle:p.title, pathwayId:p.id}))); }
function findCourse(id){ return allCourses().find(c=>c.id===id); }
function moduleByNumber(n){ return ORIENTATION.modules.find(m=>m.number===Number(n)); }

function showSection(id, pushHash=true){
  state.section=id;
  document.querySelectorAll('.section').forEach(s=>s.classList.toggle('active',s.id===id));
  document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.section===id));
  if(pushHash) history.pushState(null,'',id==='home' ? '#home' : '#'+id);
  window.scrollTo({top:0,behavior:'smooth'});
}

function renderPathways(){
  const wrap=document.getElementById('pathways');
  wrap.innerHTML=PATHWAYS.map(p=>`
    <div class="pathway">
      <div class="pathway-banner"><h3>${esc(p.title)}</h3><p>${esc(p.subtitle)}</p></div>
      <div class="card-grid course-grid">
        ${p.courses.map(c=>{
          const detail = c.id==='welcome-orientation' ? '10 modules • 46 lessons' : `${c.lessons.length} lessons`;
          return `<button class="card course-card" onclick="openCourse('${c.id}')">
            <span class="badge">${esc(c.category)}</span><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p>
            <div class="course-meta"><span>${detail}</span><span class="arrow">›</span></div></button>`;
        }).join('')}
      </div>
    </div>`).join('');
}

function renderBlocks(items){
  if(!items || !items.length) return '';
  let html='', mode=null, list=[];
  const flush=()=>{ if(!list.length) return; html += mode==='ol' ? `<ol>${list.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>` : `<ul>${list.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`; list=[]; mode=null; };
  items.forEach(item=>{
    const s=String(item).trim();
    if(/^•\s+/.test(s)){
      if(mode && mode!=='ul') flush(); mode='ul'; list.push(s.replace(/^•\s+/,'')); return;
    }
    if(/^\d+\.\s+/.test(s)){
      if(mode && mode!=='ol') flush(); mode='ol'; list.push(s.replace(/^\d+\.\s+/,'')); return;
    }
    flush();
    if(s.length<55 && !/[.!?:]$/.test(s) && !s.includes('—')) html += `<h4>${esc(s)}</h4>`;
    else html += `<p>${esc(s)}</p>`;
  });
  flush(); return html;
}

function requiredReadingHTML(){
  return `<div class="section-head"><div><h2>Required Reading</h2><p>These PDFs are included in the app package.</p></div></div>
    <div class="card-grid">
    ${ORIENTATION.required_reading.map((r,i)=>`<div class="card resource-file"><div class="file-icon">📄</div><div><h3>${esc(r.title)}</h3><p>${i===0?'Student policies, expectations, scope, timelines, and handbook guidance.':i===1?'Orientation reference guide for students, members, and learners.':'Full NHMEC 100 course document used for this in-app class.'}</p><a class="btn btn-sage file-link" href="${encodeURI(r.file)}" target="_blank" rel="noopener">Open PDF</a></div></div>`).join('')}
    </div>`;
}

function openOrientationCourse(pushHash=true){
  const complete=JSON.parse(localStorage.getItem('nhmec-orientation-complete')||'{}');
  const total=ORIENTATION.modules.reduce((a,m)=>a+m.lessons.length,0);
  const done=Object.values(complete).filter(Boolean).length;
  const pct=Math.round(done/total*100)||0;
  document.getElementById('courseDetail').innerHTML=`
    <div class="backbar"><button class="backbtn" onclick="showSection('courses')">← All courses</button></div>
    <div class="detail-hero"><span class="badge">NHMEC 100 • Required Orientation</span><h2>${esc(ORIENTATION.title)}</h2><p>${esc(ORIENTATION.subtitle)}</p></div>
    <div class="card"><h3>Course overview</h3><p>${esc(ORIENTATION.description)}</p><div class="lesson-callout"><b>Student focus:</b> ${esc(ORIENTATION.student_focus)}</div></div>
    <div class="card"><div class="course-progress-head"><div><h3>Your orientation progress</h3><p>${done} of ${total} lessons marked complete</p></div><b>${pct}%</b></div><div class="progress"><span style="width:${pct}%"></span></div></div>
    ${requiredReadingHTML()}
    <div class="section-head"><div><h2>10 Orientation Modules</h2><p>Open a module to read the real NHMEC lessons, reflection, and assignment.</p></div></div>
    <div class="card-grid">
      ${ORIENTATION.modules.map(m=>`<button class="card lesson-card module-card" onclick="openOrientationModule(${m.number})"><span class="lesson-number">${m.number}</span><span><h3>${esc(m.title)}</h3><p>${m.lessons.length} lessons${m.extras.assignment?' • reflection & assignment':''}</p></span><span class="arrow">›</span></button>`).join('')}
    </div>
    <div class="card assessment-promo"><span class="badge">Final Assessment</span><h3>25-Question Open-Book Orientation Assessment</h3><p>Passing score: 70% minimum. Students may review the orientation material and retake the assessment if needed.</p><button class="btn btn-green" onclick="openOrientationAssessment()">Take assessment</button></div>`;
  showSection('course-detail',false);
  if(pushHash) history.pushState(null,'','#course/welcome-orientation');
}

function openCourse(id,pushHash=true){
  if(id==='welcome-orientation') return openOrientationCourse(pushHash);
  const c=findCourse(id); if(!c)return;
  state.currentCourse=id; state.currentLesson=null;
  const req=c.requirements?.length?`<div class="card"><h3>Practitioner requirements</h3><div class="requirements">${c.requirements.map(x=>`<span class="req">${esc(x)}</span>`).join('')}</div></div>`:'';
  document.getElementById('courseDetail').innerHTML=`
    <div class="backbar"><button class="backbtn" onclick="showSection('courses')">← All courses</button></div>
    <div class="detail-hero"><span class="badge">${esc(c.pathwayTitle)}</span><h2>${esc(c.title)}</h2><p>${esc(c.description)}</p></div>
    <div class="card"><h3>Learning outcomes</h3><ul class="outcomes">${c.outcomes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>${req}
    <div class="section-head"><div><h2>Lessons</h2><p>Open a lesson to begin studying.</p></div><small>${c.lessons.length} total</small></div>
    <div class="card-grid">${c.lessons.map((l,i)=>`<button class="card lesson-card" onclick="openLesson('${c.id}',${i})"><span class="lesson-number">${i+1}</span><span><h3>${esc(l[0])}</h3><p>${esc(l[1])}</p></span><span class="arrow">›</span></button>`).join('')}</div>`;
  showSection('course-detail',false); if(pushHash)history.pushState(null,'',`#course/${id}`);
}

function openOrientationModule(n,pushHash=true){
  const m=moduleByNumber(n); if(!m)return;
  const extras=[];
  if(m.extras.reflection) extras.push(`<div class="card assignment-card"><span class="badge">Reflection</span><h3>Module ${m.number} Reflection</h3>${renderBlocks(m.extras.reflection)}</div>`);
  if(m.extras.assignment) extras.push(`<div class="card assignment-card"><span class="badge">Assignment</span><h3>Module ${m.number} Assignment</h3>${renderBlocks(m.extras.assignment)}</div>`);
  if(m.extras.final_assignment) extras.push(`<div class="card assignment-card"><span class="badge">Final Portfolio</span><h3>Final Orientation Assignment</h3>${renderBlocks(m.extras.final_assignment)}</div>`);
  if(m.extras.final_agreement) extras.push(`<div class="card assignment-card"><span class="badge">Required Agreement</span><h3>Final Orientation Agreement</h3>${renderBlocks(m.extras.final_agreement)}</div>`);
  document.getElementById('lessonDetail').innerHTML=`
    <div class="backbar"><button class="backbtn" onclick="openOrientationCourse()">← Welcome & Orientation</button></div>
    <div class="detail-hero"><span class="badge">Module ${m.number} of 10</span><h2>${esc(m.title)}</h2><p>${esc((m.purpose||[]).join(' '))}</p></div>
    <div class="card"><h3>Learning objectives</h3><ul class="outcomes">${m.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>
    <div class="section-head"><div><h2>Module Lessons</h2><p>Read each lesson in order.</p></div><small>${m.lessons.length} lessons</small></div>
    <div class="card-grid">${m.lessons.map((l,i)=>`<button class="card lesson-card" onclick="openOrientationLesson(${m.number},${i})"><span class="lesson-number">${esc(l.number)}</span><span><h3>${esc(l.title)}</h3><p>${lessonStatus(m.number,i)}</p></span><span class="arrow">›</span></button>`).join('')}</div>
    ${extras.join('')}
    ${m.number===10?`<div class="card assessment-promo"><span class="badge">Final Assessment</span><h3>Complete the orientation assessment</h3><p>25 open-book questions • 70% minimum passing score.</p><button class="btn btn-green" onclick="openOrientationAssessment()">Take assessment</button></div>`:''}`;
  showSection('lesson-detail',false); if(pushHash)history.pushState(null,'',`#orientation/module/${m.number}`);
}

function lessonKey(moduleNum,index){ return `${moduleNum}-${index}`; }
function lessonStatus(moduleNum,index){
  const complete=JSON.parse(localStorage.getItem('nhmec-orientation-complete')||'{}');
  return complete[lessonKey(moduleNum,index)] ? '✓ Completed' : 'Open lesson';
}
function toggleOrientationComplete(moduleNum,index){
  const complete=JSON.parse(localStorage.getItem('nhmec-orientation-complete')||'{}');
  const key=lessonKey(moduleNum,index); complete[key]=!complete[key]; localStorage.setItem('nhmec-orientation-complete',JSON.stringify(complete));
  openOrientationLesson(moduleNum,index,false);
}

function openOrientationLesson(moduleNum,index,pushHash=true){
  const m=moduleByNumber(moduleNum); if(!m||!m.lessons[index])return; const l=m.lessons[index];
  const complete=JSON.parse(localStorage.getItem('nhmec-orientation-complete')||'{}'); const done=!!complete[lessonKey(moduleNum,index)];
  let next='';
  if(index<m.lessons.length-1) next=`<button class="btn btn-green" onclick="openOrientationLesson(${moduleNum},${index+1})">Next lesson →</button>`;
  else if(moduleNum<10) next=`<button class="btn btn-green" onclick="openOrientationModule(${moduleNum+1})">Next module →</button>`;
  else next=`<button class="btn btn-green" onclick="openOrientationAssessment()">Final assessment →</button>`;
  document.getElementById('lessonDetail').innerHTML=`
    <div class="backbar"><button class="backbtn" onclick="openOrientationModule(${moduleNum})">← Module ${moduleNum}</button></div>
    <div class="detail-hero"><span class="badge">Lesson ${esc(l.number)}</span><h2>${esc(l.title)}</h2><p>NHMEC 100 • Welcome & Orientation</p></div>
    <article class="card lesson-body real-lesson">${renderBlocks(l.content)}
      <div class="complete-box"><button class="btn ${done?'btn-sage':'btn-green'}" onclick="toggleOrientationComplete(${moduleNum},${index})">${done?'✓ Lesson completed — tap to undo':'Mark lesson complete'}</button></div>
      <div class="lesson-nav"><button class="btn btn-sage" onclick="openOrientationModule(${moduleNum})">Module contents</button>${next}</div>
    </article>`;
  showSection('lesson-detail',false); if(pushHash)history.pushState(null,'',`#orientation/lesson/${moduleNum}/${index}`);
}

function openOrientationAssessment(pushHash=true){ state.orientationQuizIndex=0; state.orientationQuizScore=0; state.orientationAnswered=false; renderOrientationQuestion(); showSection('lesson-detail',false); if(pushHash)history.pushState(null,'','#orientation/assessment'); }
function renderOrientationQuestion(){
  const i=state.orientationQuizIndex, q=ORIENTATION.assessment_questions[i];
  if(!q){
    const pct=Math.round(state.orientationQuizScore/ORIENTATION.assessment_questions.length*100); const pass=pct>=70;
    document.getElementById('lessonDetail').innerHTML=`<div class="backbar"><button class="backbtn" onclick="openOrientationCourse()">← Welcome & Orientation</button></div><div class="detail-hero"><span class="badge">Assessment Complete</span><h2>${pass?'Passed — '+pct+'%':'Review & Retake — '+pct+'%'}</h2><p>You answered ${state.orientationQuizScore} of ${ORIENTATION.assessment_questions.length} correctly. NHMEC lists a 70% minimum passing score for this orientation assessment.</p></div><div class="card"><h3>${pass?'Orientation assessment passed':'Keep studying'}</h3><p>${pass?'You may continue into your assigned NHMEC learning pathway after completing the other required orientation acknowledgments and assignments.':'Review the modules, required reading, and scope language, then retake the open-book assessment.'}</p><button class="btn btn-green" onclick="openOrientationAssessment(false)">Retake assessment</button></div>`; return;
  }
  const pct=Math.round(i/ORIENTATION.assessment_questions.length*100);
  document.getElementById('lessonDetail').innerHTML=`<div class="backbar"><button class="backbtn" onclick="openOrientationCourse()">← Welcome & Orientation</button></div><div class="detail-hero"><span class="badge">Final Open-Book Assessment</span><h2>Question ${i+1} of ${ORIENTATION.assessment_questions.length}</h2><p>Passing score: 70% minimum.</p></div><div class="progress"><span style="width:${pct}%"></span></div><div class="quiz-card"><h3>${esc(q.q)}</h3><div id="orientationAnswers">${q.options.map(o=>`<button class="answer" onclick="answerOrientation('${o.letter}',this)"><b>${o.letter}.</b> ${esc(o.text)}</button>`).join('')}</div><div class="quiz-feedback" id="orientationFeedback"></div><button id="orientationNext" class="btn btn-green" style="display:none" onclick="nextOrientationQuestion()">${i===ORIENTATION.assessment_questions.length-1?'See results':'Next question'}</button></div>`;
}
function answerOrientation(letter,btn){
  if(state.orientationAnswered)return; state.orientationAnswered=true; const q=ORIENTATION.assessment_questions[state.orientationQuizIndex];
  const buttons=[...document.querySelectorAll('#orientationAnswers .answer')]; buttons.forEach((b,idx)=>{ if(q.options[idx].letter===q.correct)b.classList.add('correct'); });
  if(letter!==q.correct)btn.classList.add('wrong'); else state.orientationQuizScore++;
  document.getElementById('orientationFeedback').innerHTML=letter===q.correct?'<b>Correct.</b>':'<b>Review this item.</b> The correct answer is highlighted.';
  document.getElementById('orientationNext').style.display='inline-block';
}
function nextOrientationQuestion(){ state.orientationQuizIndex++; state.orientationAnswered=false; renderOrientationQuestion(); window.scrollTo({top:0,behavior:'smooth'}); }

function openLesson(courseId,index,pushHash=true){
  if(courseId==='welcome-orientation') return openOrientationModule(index+1,pushHash);
  const c=findCourse(courseId); if(!c||!c.lessons[index])return; const l=c.lessons[index];
  const next=index<c.lessons.length-1?`<button class="btn btn-green" onclick="openLesson('${courseId}',${index+1})">Next lesson →</button>`:`<button class="btn btn-green" onclick="openCourse('${courseId}')">Back to course</button>`;
  document.getElementById('lessonDetail').innerHTML=`<div class="backbar"><button class="backbtn" onclick="openCourse('${courseId}')">← ${esc(c.title)}</button></div><div class="detail-hero"><span class="badge">Lesson ${index+1} of ${c.lessons.length}</span><h2>${esc(l[0])}</h2><p>${esc(l[1])}</p></div><div class="card lesson-body"><h3>Lesson overview</h3><p>This lesson page is ready for the original PENothecary™ class content when that course is imported.</p><div class="lesson-callout"><b>Study focus:</b> ${esc(l[1])}</div><div class="lesson-nav"><button class="btn btn-sage" onclick="openCourse('${courseId}')">Course contents</button>${next}</div></div>`;
  showSection('lesson-detail',false); if(pushHash)history.pushState(null,'',`#lesson/${courseId}/${index}`);
}

function renderHerbs(filter=''){
  const q=filter.trim().toLowerCase(); const list=HERBS.filter(h=>[h.common,h.latin,h.parts,h.actions,h.prep,h.notes].join(' ').toLowerCase().includes(q));
  document.getElementById('herbCount').textContent=`${list.length} herb${list.length===1?'':'s'}`;
  document.getElementById('herbGrid').innerHTML=list.map(h=>`<details class="card herb-card"><summary><h3>${esc(h.common)}</h3><div class="latin">${esc(h.latin)}</div></summary><div class="meta"><b>Parts used</b><span>${esc(h.parts)}</span><b>Actions</b><span>${esc(h.actions)}</span><b>Preparations</b><span>${esc(h.prep)}</span><b>Study notes</b><span>${esc(h.notes)}</span><b>Safety</b><span>${esc(h.safety)}</span></div></details>`).join('')||`<div class="notice">No herbs matched that search yet.</div>`;
}
function renderQuiz(){ const q=QUIZ[state.quizIndex],pct=(state.quizIndex/QUIZ.length)*100; document.getElementById('quizProgress').style.width=pct+'%'; document.getElementById('quizStatus').textContent=`Question ${state.quizIndex+1} of ${QUIZ.length}`; document.getElementById('quizArea').innerHTML=`<div class="quiz-card"><h3>${esc(q.q)}</h3><div>${q.answers.map((a,i)=>`<button class="answer" onclick="answerQuiz(${i},this)">${esc(a)}</button>`).join('')}</div><div class="quiz-feedback" id="quizFeedback"></div><button id="nextQuiz" class="btn btn-green" style="display:none" onclick="nextQuiz()">Next question</button></div>`; state.answered=false; }
function answerQuiz(i,btn){ if(state.answered)return; state.answered=true; const q=QUIZ[state.quizIndex],buttons=[...document.querySelectorAll('.answer')]; buttons[q.correct].classList.add('correct'); if(i!==q.correct)btn.classList.add('wrong'); if(i===q.correct)state.score++; document.getElementById('quizFeedback').innerHTML=`<b>${i===q.correct?'Correct.':'Not quite.'}</b> ${esc(q.explain)}`; document.getElementById('nextQuiz').style.display='inline-block'; }
function nextQuiz(){ state.quizIndex++; if(state.quizIndex>=QUIZ.length){ document.getElementById('quizProgress').style.width='100%';document.getElementById('quizStatus').textContent='Completed';document.getElementById('quizArea').innerHTML=`<div class="quiz-card"><h3>Study quiz complete 🌿</h3><p>You scored <b>${state.score} out of ${QUIZ.length}</b>.</p><button class="btn btn-green" onclick="restartQuiz()">Take it again</button></div>`;} else renderQuiz(); }
function restartQuiz(){state.quizIndex=0;state.score=0;state.answered=false;renderQuiz();}

function routeFromHash(){
  const h=location.hash.replace(/^#/,''); if(!h||h==='home')return showSection('home',false);
  if(h==='orientation/assessment')return openOrientationAssessment(false);
  if(h.startsWith('orientation/module/'))return openOrientationModule(Number(h.split('/')[2]),false);
  if(h.startsWith('orientation/lesson/')){const p=h.split('/');return openOrientationLesson(Number(p[2]),Number(p[3]),false);}
  if(h.startsWith('course/'))return openCourse(h.split('/')[1],false);
  if(h.startsWith('lesson/')){const p=h.split('/');return openLesson(p[1],Number(p[2]),false);}
  if(['courses','herbs','quiz','resources'].includes(h))return showSection(h,false); showSection('home',false);
}

document.addEventListener('DOMContentLoaded',()=>{ renderPathways();renderHerbs();renderQuiz(); document.getElementById('herbSearch').addEventListener('input',e=>renderHerbs(e.target.value)); document.querySelectorAll('[data-go]').forEach(x=>x.addEventListener('click',()=>showSection(x.dataset.go))); document.querySelectorAll('.nav-btn').forEach(x=>x.addEventListener('click',()=>showSection(x.dataset.section))); routeFromHash(); });
window.addEventListener('popstate',routeFromHash);
if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));}
